#!/usr/bin/env bash
# Usage: bash scripts/binance-key-wizard.sh
# Walks you through creating a read-only Binance futures key into .local/binance.env and probes it.
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Keys live in .local/ (gitignored, next to the agent master key), never in .env.
ENV_FILE=".local/binance.env"
PROBE="scripts/binance-key-probe.mjs"
PROBE_LOG=".local/binance-key-probe.log"

# run_probe [flags...] runs the read-only probe inside devbox when available
# and tees the report to PROBE_LOG. Returns the probe's exit code.
run_probe() {
  local rc=0
  export NODE_USE_ENV_PROXY=1   # let Node fetch honour HTTPS_PROXY if the machine needs one
  if command -v devbox >/dev/null 2>&1; then
    devbox run -- node "$PROBE" "$@" 2>&1 | tee -a "$PROBE_LOG" || rc=${PIPESTATUS[0]}
  else
    node "$PROBE" "$@" 2>&1 | tee -a "$PROBE_LOG" || rc=${PIPESTATUS[0]}
  fi
  return "$rc"
}

run_wizard() {

TOTAL_STAGES=6
mkdir -p "$(dirname "$ENV_FILE")"

banner "Binance read-only futures key for the journal"

# ── 1. create the key with Enable Reading only ─────────────────────────────
stage "Binance: create a system-generated key"
say "One key per linked account. Start with the minimum permission set;"
say "later stages tell you if Binance also needs 'Enable Futures' for reads."
open_url "https://www.binance.com/en/my/settings/api-management"
step "Click 'Create API' → choose 'System generated' (HMAC) → label it 'trading-journal'."
step "Complete 2FA. On the new key's panel click 'Edit restrictions'."
step "Tick ONLY 'Enable Reading'. Leave unticked: Enable Futures, Enable Spot & Margin Trading,"
step "  Enable Margin, Enable Withdrawals, Enable Internal Transfer, Enable Vanilla Options,"
step "  Enable Portfolio Margin Trading, universal transfer, FIX."
step "Copy the API key and the secret (the secret is shown once only)."
warn "If the Futures permission is greyed out, the key predates futures activation or"
warn "Portfolio Margin is on: create the key from the account that actually trades."
ask BINANCE_API_KEY "Paste the API key:"
ask_secret BINANCE_API_SECRET "Paste the secret key:"
write_env BINANCE_API_KEY "$BINANCE_API_KEY"
write_env BINANCE_API_SECRET "$BINANCE_API_SECRET"
note "stored in $ENV_FILE (mode 0600, gitignored). Never paste it into the repo or a ticket."

# ── 2. IP restriction ──────────────────────────────────────────────────────
stage "Binance: IP restriction"
say "An unrestricted HMAC key is forced to reading-only by Binance policy."
say "Restrict to this machine's IPv4 only if it is fixed; otherwise leave unrestricted."
step "On the key's panel: 'Unrestricted (Less Secure)' or 'Restrict access to trusted IPs only'."
if confirm "Did you restrict the key to a trusted IP?"; then
  write_env BINANCE_KEY_IP_RESTRICTED "yes"
else
  write_env BINANCE_KEY_IP_RESTRICTED "no"
fi
pause "Click 'Save' on Binance, then press Enter."

# ── 3. probe with Enable Reading only ─────────────────────────────────────
stage "Probe: do futures reads work with Enable Reading only?"
say "Runs signed READ calls only (apiRestrictions, balance, income, orders, positions)."
say "This answers an UNCONFIRMED fact on the map; report is appended to $PROBE_LOG."
pause "Press Enter to run the probe."
if run_probe; then
  write_env BINANCE_KEY_ENABLE_FUTURES "no"
  note "Futures reads work without 'Enable Futures'. Keep it unticked."
else
  warn "A probe failed. If 'futures balance' was rejected (code -2015), Binance needs 'Enable Futures'."
  if confirm "Tick 'Enable Futures' on Binance and re-run the probe?"; then
    step "Edit restrictions → tick 'Enable Futures' → Save (2FA again)."
    pause "Press Enter once saved."
    if run_probe; then
      write_env BINANCE_KEY_ENABLE_FUTURES "yes"
    else
      write_env BINANCE_KEY_ENABLE_FUTURES "yes"
      SKIPPED+=("probe still failing with Enable Futures on: read $PROBE_LOG and report it on task-48")
    fi
  else
    SKIPPED+=("probe failed and Enable Futures was not tried: read $PROBE_LOG")
  fi
fi

# ── 4. optional write probe ───────────────────────────────────────────────
stage "Probe: is the key rejected on a write endpoint?"
say "POST /fapi/v1/order/test only validates an order and never places one."
say "A reading-only key should be rejected; acceptance means the key can trade."
if confirm "Run the write probe now?"; then
  if run_probe --write-probe; then
    write_env BINANCE_KEY_WRITE_PROBE "rejected"
  else
    write_env BINANCE_KEY_WRITE_PROBE "see-log"
    SKIPPED+=("write probe did not pass cleanly: read $PROBE_LOG")
  fi
else
  write_env BINANCE_KEY_WRITE_PROBE "skipped"
fi

# ── 5. optional demo testnet key ──────────────────────────────────────────
stage "Optional: demo testnet key (demo-fapi.binance.com)"
say "Useful for e2e tests without touching the live account. Separate keys and data."
if confirm "Create a testnet key now?"; then
  open_url "https://testnet.binancefuture.com/en/futures/BTCUSDT"
  step "Log in (GitHub/Google), open 'API Key' at the bottom panel, copy key + secret."
  ask BINANCE_TESTNET_API_KEY "Paste the testnet API key:"
  ask_secret BINANCE_TESTNET_API_SECRET "Paste the testnet secret:"
  write_env BINANCE_TESTNET_API_KEY "$BINANCE_TESTNET_API_KEY"
  write_env BINANCE_TESTNET_API_SECRET "$BINANCE_TESTNET_API_SECRET"
  note "Probe it with: BINANCE_API_KEY=\$BINANCE_TESTNET_API_KEY BINANCE_API_SECRET=... node $PROBE --testnet"
else
  write_env BINANCE_TESTNET_API_KEY ""
  note "Skipped. Re-run this wizard later to add one."
fi

# ── 6. record for the ticket ──────────────────────────────────────────────
stage "Record the outcome on task-48"
say "Paste the probe summary (no secrets) into the ticket so the next session can close it:"
note "backlog task edit task-48 --append-notes \"\$(grep -E '^[✓✗·–]' $PROBE_LOG)\""
say "Values recorded in $ENV_FILE:"
note "  BINANCE_KEY_IP_RESTRICTED, BINANCE_KEY_ENABLE_FUTURES, BINANCE_KEY_WRITE_PROBE, testnet key"
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
